import { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { updateUserProfile } from '../../services/api';
import { setUser } from '../../store/slices/authSlice';

function UserForm({ onCancel, initialFirstName, initialLastName }) {
    const [firstName, setFirstName] = useState(initialFirstName || '');
    const [lastName, setLastName] = useState(initialLastName || '');
    const [error, setError] = useState(null);
    const { user, token } = useSelector((state) => state.auth);
    const dispatch = useDispatch();

    // S'assurer que les champs sont à jour
    useEffect(() => {
        if (user?.firstName && firstName !== user.firstName) {
            setFirstName(user.firstName);
        }
        if (user?.lastName && lastName !== user.lastName) {
            setLastName(user.lastName);
        }
    }, [user?.firstName, user?.lastName, firstName, lastName]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const updatedUser = await updateUserProfile({
                firstName: firstName.trim(),
                lastName: lastName.trim()
            }, token);

            // Mettre à jour le store avec les nouvelles données
            dispatch(setUser({
                ...user,
                firstName: firstName.trim(),
                lastName: lastName.trim()
            }));

            setError(null);
            if (onCancel) onCancel();
        } catch (error) {
            setError('Failed to update user information');
            console.error('Update error:', error);
        }
    };

    const handleCancel = () => {
        setFirstName(initialFirstName || '');
        setLastName(initialLastName || '');
        setError(null);
        if (onCancel) onCancel();
    };

    return (
        <div className="edit-form-container">
            <h3>Edit user info</h3>
            <form onSubmit={handleSubmit} className="edit-username-form">
                <div className="input-container">
                    <label htmlFor="firstName">First name:</label>
                    <input
                        type="text"
                        id="firstName"
                        value={firstName}
                        onChange={(e) => setFirstName(e.target.value)}
                        required
                        autoFocus
                    />
                </div>
                <div className="input-container">
                    <label htmlFor="lastName">Last name:</label>
                    <input
                        type="text"
                        id="lastName"
                        value={lastName}
                        onChange={(e) => setLastName(e.target.value)}
                        required
                    />
                </div>
                <div className="form-btn-container">
                    <button type="submit" className="edit-button">
                        Save
                    </button>
                    <button
                        type="button"
                        className="edit-button cancel-btn"
                        onClick={handleCancel}
                    >
                        Cancel
                    </button>
                </div>
            </form>
            {error && <p className="error-txt">{error}</p>}
        </div>
    );
}

export default UserForm;
